declarations.body:
{
  name: resourceGroupName
  location: location
  tags: tags
}

{
  scope: tenant()
  name: azureMonitorSliServiceGroupName
  properties: {
    displayName: '${appName} ${environment}'
    parent: {
      resourceId: azureMonitorSliEffectiveParentServiceGroupId
    }
  }
}

{
  name: registryName
  location: location
  tags: tags
  sku: {
    name: 'Premium' // Private Endpoint requires Premium SKU
  }
  properties: {
    adminUserEnabled: false
    dataEndpointEnabled: false
    publicNetworkAccess: 'Enabled'
    networkRuleBypassOptions: 'AzureServices'
    encryption: {
      status: 'disabled'
    }
    policies: {
      quarantinePolicy: { status: 'disabled' }
      trustPolicy: { type: 'Notary', status: 'disabled' }
      retentionPolicy: { days: 7, status: 'disabled' }
    }
  }
}

{
  name: 'privatelink.azurecr.io'
  location: 'global'
  tags: tags
}

{
  parent: containerRegistryPrivateDnsZone
  name: 'vnetlink-${registryName}'
  location: 'global'
  properties: {
    registrationEnabled: false
    virtualNetwork: { id: vnetId }
  }
}

{
  name: 'pe-${registryName}'
  location: location
  tags: tags
  properties: {
    subnet: { id: privateEndpointSubnetId }
    #disable-next-line BCP037
    ipVersionType: 'IPv4'
    privateLinkServiceConnections: [
      {
        name: 'plsc-${registryName}'
        properties: {
          privateLinkServiceId: containerRegistry.id
          groupIds: ['registry']
        }
      }
    ]
  }
}

{
  parent: containerRegistryPrivateEndpoint
  name: 'default'
  properties: {
    privateDnsZoneConfigs: [
      { name: 'registry-config', properties: { privateDnsZoneId: containerRegistryPrivateDnsZone.id } }
    ]
  }
  dependsOn: [
    containerRegistryPrivateDnsZoneLink
  ]
}

[
  for principalId in principalObjectIds: {
    name: guid(containerRegistry.id, principalId, 'AcrPull')
    scope: containerRegistry
    properties: {
      roleDefinitionId: subscriptionResourceId(
        'Microsoft.Authorization/roleDefinitions',
        '7f951dda-4ed3-4680-a7ca-43fe172d538d'
      )
      principalId: principalId
      principalType: 'ServicePrincipal'
    }
  }
]

{
  name: 'id-${aksName}'
  location: location
  tags: tags
}

{
  name: aksName
  location: location
  tags: tags
  // Enable Uptime SLA by switching AKS SKU tier
  sku: {
    name: skuName
    tier: 'Standard'
  }
  identity: {
    type: 'UserAssigned'
    userAssignedIdentities: {
      '${aksIdentity.id}': {}
    }
  }
  properties: aksBaseProperties
  dependsOn: [
    aksSubnetNetworkContributorRole
  ]
}

{
  name: virtualNetworkName
}

{
  name: subnetName
  parent: existingVirtualNetwork
}

{
  name: guid(existingAksSubnet.id, 'NetworkContributor', aksIdentity.name)
  scope: existingAksSubnet
  properties: {
    roleDefinitionId: networkContributorRoleId
    principalId: aksIdentity.properties.principalId
    principalType: 'ServicePrincipal'
  }
}

{
  name: guid(resourceGroup().id, 'NetworkContributor', aksIdentity.name)
  properties: {
    roleDefinitionId: networkContributorRoleId
    principalId: aksIdentity.properties.principalId
    principalType: 'ServicePrincipal'
  }
}

{
  parent: aksCluster
  name: 'aksManagedNodeOSUpgradeSchedule'
  properties: {
    maintenanceWindow: {
      durationHours: 4
      schedule: {
        weekly: {
          dayOfWeek: 'Wednesday'
          intervalWeeks: 1
        }
      }
      startDate: '2025-04-01'
      startTime: '00:00'
      utcOffset: '+09:00'
    }
  }
}

{
  name: 'aks-nodeos-autoupgrade'
  location: location
  tags: tags
  kind: 'LogAlert'
  identity: {
    type: 'SystemAssigned'
  }
  properties: {
    displayName: 'aks-nodeos-autoupgrade'
    description: 'AKS Node OS auto-upgrade detected via ARG events'
    enabled: true
    scopes: [aksCluster.id]
    evaluationFrequency: 'PT30M'
    windowSize: 'PT60M'
    severity: 3
    autoMitigate: true
    criteria: {
      allOf: [
        {
          query: aksNodeOsAutoUpgradeKql
          timeAggregation: 'Count'
          operator: 'GreaterThan'
          threshold: 0
          metricMeasureColumn: ''
          dimensions: [
            {
              name: 'status'
              operator: 'Include'
              values: ['*']
            }
          ]
        }
      ]
    }
    actions: {
      actionGroups: actionGroupId != '' ? [actionGroupId] : []
    }
  }
}

{
  name: guid(subscription().id, resourceGroup().id, 'aks-nodeos-autoupgrade', 'Reader', aksAlertPrincipalId)
  scope: resourceGroup()
  properties: {
    principalId: aksAlertPrincipalId
    principalType: 'ServicePrincipal'
    roleDefinitionId: readerRoleDefinitionId
  }
}

{
  name: guid(subscription().id, resourceGroup().id, 'fleet-approval-pending', 'Reader', fleetAlertPrincipalId)
  scope: resourceGroup()
  properties: {
    principalId: fleetAlertPrincipalId
    principalType: 'ServicePrincipal'
    roleDefinitionId: readerRoleDefinitionId
  }
}

{
  name: guid(subscription().id, 'aks-nodeos-autoupgrade-alert', 'Reader', aksAlertPrincipalId)
  properties: {
    principalId: aksAlertPrincipalId
    principalType: 'ServicePrincipal'
    roleDefinitionId: readerRoleDefinitionId
  }
}

{
  name: guid(subscription().id, 'fleet-pending-approval-alert', 'Reader', fleetAlertPrincipalId)
  properties: {
    principalId: fleetAlertPrincipalId
    principalType: 'ServicePrincipal'
    roleDefinitionId: readerRoleDefinitionId
  }
}

{
