    ]
  }
}

resource expIOChaos 'Microsoft.Chaos/experiments@2025-01-01' = if (enableIOChaos) {
  name: 'exp-aks-io'
  location: location
  identity: {
    type: 'SystemAssigned'
  }
  tags: tags
  properties: {
    selectors: [selector]
    steps: [
      {
        name: 'step1'
        branches: [
          {
            name: 'branch1'
            actions: [
              {
                name: 'urn:csci:microsoft:azureKubernetesServiceChaosMesh:ioChaos/2.2'
                type: 'continuous'
                selectorId: 'aks'
