                parameters: [
                  {
                    key: 'jsonSpec'
                    value: string(ioChaosSpec)
                  }
                ]
              }
            ]
          }
        ]
      }
    ]
  }
}

resource expTimeChaos 'Microsoft.Chaos/experiments@2025-01-01' = if (enableTimeChaos) {
  name: 'exp-aks-time'
  location: location
  identity: {
    type: 'SystemAssigned'
  }
  tags: tags
  properties: {
    selectors: [selector]
    steps: [
      {
        name: 'step1'
        branches: [
          {
            name: 'branch1'
            actions: [
              {
                name: 'urn:csci:microsoft:azureKubernetesServiceChaosMesh:timeChaos/2.2'
                type: 'continuous'
