sources.infra/modules/network.bicep:
@description('Deployment location')
param location string
@description('Tags object')
param tags object
@description('Virtual network name')
param vnetName string
@description('VNet address prefix')
param vnetAddressPrefix string
@description('AKS subnet prefix')
param aksSubnetPrefix string
@description('Private Endpoint subnet prefix')
param peSubnetPrefix string
@description('AKS API Server subnet prefix')
param aksApiSubnetPrefix string
@description('Function App Flex Consumption subnet prefix')
param functionSubnetPrefix string
@description('Resource token for unique naming')
param resourceToken string
@description('Dedicated SRE Agent subnet prefix (/27 or larger)')
param sreAgentSubnetPrefix string

resource virtualNetwork 'Microsoft.Network/virtualNetworks@2026-03-01' = {
  name: vnetName
  location: location
  tags: tags
  properties: {
    addressSpace: {
      addressPrefixes: [vnetAddressPrefix]
    }
    subnets: [
      {
        name: 'snet-aks'
        properties: {
          addressPrefix: aksSubnetPrefix
          networkSecurityGroup: {
            id: aksSubnetNetworkSecurityGroup.id
          }
          privateEndpointNetworkPolicies: 'Disabled'
          defaultOutboundAccess: false
        }
      }
      {
        name: 'snet-pe'
        properties: {
          addressPrefix: peSubnetPrefix
          privateEndpointNetworkPolicies: 'Disabled'
          defaultOutboundAccess: false
        }
      }
      {
        name: 'snet-aks-api'
        properties: {
          addressPrefix: aksApiSubnetPrefix
          privateEndpointNetworkPolicies: 'Disabled'
          defaultOutboundAccess: false
          delegations: [
            {
              name: 'Microsoft.ContainerService.managedClusters'
              properties: {
                serviceName: 'Microsoft.ContainerService/managedClusters'
              }
            }
          ]
        }
      }
      {
        name: 'snet-func'
        properties: {
          addressPrefix: functionSubnetPrefix
          defaultOutboundAccess: false
          delegations: [
            {
              name: 'Microsoft.App.environments'
              properties: {
                serviceName: 'Microsoft.App/environments'
              }
            }
          ]
        }
      }
      // Keep the subnet when an existing Agent is disabled in incremental deployments.
      {
        name: 'snet-sre-agent'
        properties: {
          addressPrefix: sreAgentSubnetPrefix
          defaultOutboundAccess: false
          delegations: [
            {
              name: 'Microsoft.App.environments'
              properties: {
                serviceName: 'Microsoft.App/environments'
              }
            }
          ]
        }
      }
    ]
  }
}

@description('Network Security Group for AKS subnet')
resource aksSubnetNetworkSecurityGroup 'Microsoft.Network/networkSecurityGroups@2026-03-01' = {
  name: 'nsg-${vnetName}-snet-aks'
  location: location
  tags: tags
  properties: {
    securityRules: [
      {
        name: 'Allow-HTTP-HTTPS'
        properties: {
          priority: 1000
          direction: 'Inbound'
          access: 'Allow'
          protocol: 'Tcp'
          sourcePortRange: '*'
          destinationPortRanges: [
            '80'
            '443'
          ]
          sourceAddressPrefix: '*'
          destinationAddressPrefix: '*'
        }
      }
    ]
  }
}

resource ingressPublicIP 'Microsoft.Network/publicIPAddresses@2026-03-01' = {
  name: 'pip-ingress-${resourceToken}'
  location: location
  tags: tags
  sku: {
    name: 'Standard'
  }
  properties: {
    publicIPAllocationMethod: 'Static'
    dnsSettings: {
      domainNameLabel: 'aks-chaos-lab-${resourceToken}'
    }
  }
}

output vnetId string = virtualNetwork.id
output aksSubnetId string = resourceId('Microsoft.Network/virtualNetworks/subnets', vnetName, 'snet-aks')
output peSubnetId string = resourceId('Microsoft.Network/virtualNetworks/subnets', vnetName, 'snet-pe')
output aksApiSubnetId string = resourceId('Microsoft.Network/virtualNetworks/subnets', vnetName, 'snet-aks-api')
output functionSubnetId string = resourceId('Microsoft.Network/virtualNetworks/subnets', vnetName, 'snet-func')
output sreAgentSubnetId string = resourceId('Microsoft.Network/virtualNetworks/subnets', vnetName, 'snet-sre-agent')
output vnetNameOut string = virtualNetwork.name
